style.css:
@-moz-document domain("roblox.com") {
/* Full-page background */
    body, html {
        background-image: url(https://i.imgur.com/cny5Nuu.png) !important;
        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center center !important;
        opacity: 1 !important; /* no transparency */
        color: #fff !important; /* default text color for readability */
    }

    /* Remove any overlays or semi-transparent layers */
    .container, .viewport, .main-content, .section {
        background: none !important;
    }

    /* Optional: tweak navbar or cards for visibility */
    .navbar, .card, .modal-content, .popup {
        background-color: rgba(0, 0, 0, 0.7) !important; /* slight dark overlay for readability */
        color: #fff !important;
    }

    /* Remove Roblox default background colors for all divs */
    div {
        background: none !important;
    }

    /* Ensure text stays readable */
    a, p, span, h1, h2, h3, h4, h5, h6 {
        color: #fff !important;
    }
}
